import json

# Create the final grid
grid = [[0]*26 for _ in range(26)]

# 5s: diagonal at col = 9 + row
for r in range(26):
    c5 = 9 + r
    if 0 <= c5 < 26:
        grid[r][c5] = 5

# 4s: diagonal at col = row - 2
for r in range(26):
    if r >= 2:
        c4 = r - 2
        if 0 <= c4 < 26:
            grid[r][c4] = 4

# 3s: pairs at cols (r-8, r-7) for rows >= 8
for r in range(26):
    if r >= 8:
        c3a, c3b = r - 8, r - 7
        if 0 <= c3a < 26 and 0 <= c3b < 26:
            grid[r][c3a] = 3
            grid[r][c3b] = 3

# Output as JSON for the submit action
grid_json = [[int(x) for x in row] for row in grid]
print(json.dumps(grid_json))

